import { Task } from '../../domain/entities/Task';
import { TaskCriteria, TaskRepository } from '../../domain/repositories/TaskRepository';

export class InMemoryTaskRepository implements TaskRepository {
  private readonly tasks = new Map<string, Task>();

  async save(task: Task): Promise<void> {
    this.tasks.set(task.id, task);
  }

  async findById(id: string): Promise<Task | undefined> {
    return this.tasks.get(id);
  }

  async findByProject(projectId: string, criteria: TaskCriteria): Promise<Task[]> {
    const { status, assigneeId } = criteria;
    return [...this.tasks.values()].filter(
      (task) =>
        task.projectId === projectId &&
        (status === undefined || task.status.equals(status)) &&
        (assigneeId === undefined || task.assigneeId === assigneeId),
    );
  }
}

